#!/usr/bin/env python3
# spec-chat-capabilities: git-baseline narrow-review-root
"""spec-chat review-serve - HTTP transport for a narrow review collection.

FSA requires the browser and the spool files to share a machine; over SSH they
don't. This serves a narrow review collection plus tiny spool and Git-baseline
routes. For remote review, bind directly to the host interface and treat the
printed URL as the secret. Stdlib only.

usage: review-serve.py [ROOT] [PORT] [--public] [--bind HOST] [--host HOST]

  GET  /api/events?dir=<review-dir-rel-path>            -> ordered event list
  POST /api/events?dir=<...>&actor=human|agent  (JSON)  -> writes one event file
  GET  /api/baseline?path=<spec-rel-path>[&base=<ref>]  -> local Git baseline
"""

from __future__ import annotations

import argparse
import json
import os
import re
import socket
import subprocess
import time
from http.server import HTTPServer, SimpleHTTPRequestHandler
from pathlib import Path
from typing import TYPE_CHECKING, override
from urllib.parse import parse_qs, urlparse

if TYPE_CHECKING:
    from socketserver import BaseServer
    from typing import TypedDict

    class StoredEvent(TypedDict):
        actor: str
        name: str
        body: object


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("root", nargs="?", default=".")
    parser.add_argument("port", nargs="?", type=int, default=None)
    parser.add_argument("--public", action="store_true", help="bind to all host interfaces")
    parser.add_argument("--bind", default=None, help="bind address (default: loopback)")
    parser.add_argument(
        "--host", default=None, help="host name or address printed in the review URL"
    )
    return parser.parse_args()


ARGS = parse_args()
ROOT = os.path.realpath(ARGS.root)
root_path = Path(ROOT)
port = ARGS.port if ARGS.port is not None else (0 if ARGS.public else 7160)
BIND = ARGS.bind or ("0.0.0.0" if ARGS.public else "127.0.0.1")


def advertised_host() -> str:
    if ARGS.host:
        return ARGS.host
    if not ARGS.public:
        return "127.0.0.1"
    try:
        probe = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        probe.connect(("8.8.8.8", 80))
        address = probe.getsockname()[0]
        probe.close()
        if address and not address.startswith("127."):
            return address
    except OSError:
        pass
    return socket.gethostname()


try:
    repo_root = subprocess.check_output(
        ("/usr/bin/git", "-C", ROOT, "rev-parse", "--show-toplevel"),
        text=True,
        stderr=subprocess.DEVNULL,
    ).strip()
except (OSError, subprocess.CalledProcessError):
    repo_root = None


class _BroadReviewRootError(SystemExit):
    def __init__(self) -> None:
        super().__init__(
            "refusing broad root; serve a narrow review collection "
            "strictly inside its Git repository"
        )


if not repo_root or root_path.samefile(repo_root):
    raise _BroadReviewRootError


def _is_file(target: str) -> bool:
    try:
        return Path(target).is_file()
    except (OSError, ValueError):
        return False


class Handler(SimpleHTTPRequestHandler):
    def __init__(
        self,
        request: socket.socket | tuple[bytes, socket.socket],
        client_address: object,
        server: BaseServer,
    ) -> None:
        super().__init__(request, client_address, server, directory=ROOT)

    def end_headers(self) -> None:
        # dev loop: never let a stale runtime.js survive a reload
        self.send_header("Cache-Control", "no-cache")
        super().end_headers()

    @override
    def log_message(self, format: str, *a: object) -> None:
        line = format % a
        if "hxdebug" in line:
            super().log_message("DEBUG-BEACON: %s", line)

    def translate_path(self, path: str) -> str:
        translated = super().translate_path(path)
        resolved = os.path.realpath(translated)
        if resolved != ROOT and not resolved.startswith(ROOT + os.sep):
            return str(root_path / ".spec-chat-path-denied")
        return translated

    def _review_dir(self, q: dict[str, list[str]]) -> Path | None:
        rel = q.get("dir", [""])[0]
        d = os.path.realpath(root_path / rel)
        if not d.startswith(ROOT + os.sep) or not d.endswith(".review"):
            return None
        return Path(d)

    def _json(self, obj: object, code: int = 200) -> None:
        body = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _baseline(self, q: dict[str, list[str]]) -> None:
        rel = q.get("path", [""])[0]
        target = os.path.realpath(root_path / rel)
        if not rel or not target.startswith(ROOT + os.sep) or not _is_file(target):
            return self._json({"error": "bad path"}, 400)
        try:
            repo = subprocess.check_output(
                ("/usr/bin/git", "-C", ROOT, "rev-parse", "--show-toplevel"),
                text=True,
                stderr=subprocess.DEVNULL,
            ).strip()
            repo_rel = os.path.relpath(target, repo)
            if repo_rel.startswith(".." + os.sep) or repo_rel == "..":
                return self._json({"error": "path outside repository"}, 400)
            requested = q.get("base", [""])[0]
            candidates = [requested] if requested else []
            if not candidates:
                try:
                    candidates.append(
                        subprocess.check_output(
                            (
                                "/usr/bin/git",
                                "-C",
                                repo,
                                "symbolic-ref",
                                "--quiet",
                                "--short",
                                "refs/remotes/origin/HEAD",
                            ),
                            text=True,
                            stderr=subprocess.DEVNULL,
                        ).strip()
                    )
                except subprocess.CalledProcessError:
                    candidates.extend(("main", "master"))
            base_ref = next(
                (
                    candidate
                    for candidate in candidates
                    if candidate
                    and subprocess.run(
                        (
                            "/usr/bin/git",
                            "-C",
                            repo,
                            "rev-parse",
                            "--verify",
                            "--quiet",
                            candidate + "^{commit}",
                        ),
                        stdout=subprocess.DEVNULL,
                        stderr=subprocess.DEVNULL,
                        check=False,
                    ).returncode
                    == 0
                ),
                None,
            )
            if not base_ref:
                return self._json({"error": "no local base ref"}, 409)
            base = subprocess.check_output(
                ("/usr/bin/git", "-C", repo, "merge-base", "HEAD", base_ref),
                text=True,
                stderr=subprocess.DEVNULL,
            ).strip()
            prior = subprocess.run(
                ("/usr/bin/git", "-C", repo, "show", base + ":" + repo_rel),
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL,
                check=False,
            )
            # A newly seeded spec is absent from the change-request base. Use
            # the first committed snapshot that introduced it. This seed must
            # stay stable across later spec commits, or refresh would move the
            # baseline to HEAD and erase the review diff.
            if prior.returncode != 0:
                seed = subprocess.run(
                    ("/usr/bin/git", "-C", repo, "rev-list", "--reverse", "HEAD", "--", repo_rel),
                    stdout=subprocess.PIPE,
                    stderr=subprocess.DEVNULL,
                    text=True,
                    check=False,
                )
                seed = (
                    seed.stdout.strip().splitlines()[0]
                    if seed.returncode == 0 and seed.stdout.strip()
                    else None
                )
                if seed:
                    seed_prior = subprocess.run(
                        ("/usr/bin/git", "-C", repo, "show", seed + ":" + repo_rel),
                        stdout=subprocess.PIPE,
                        stderr=subprocess.DEVNULL,
                        check=False,
                    )
                    if seed_prior.returncode == 0:
                        prior = seed_prior
            html = prior.stdout.decode("utf-8") if prior.returncode == 0 else None
            return self._json({"base": base, "html": html})
        except (OSError, subprocess.CalledProcessError, UnicodeDecodeError):
            return self._json({"error": "git baseline unavailable"}, 409)

    def do_GET(self) -> None:
        u = urlparse(self.path)
        if u.path == "/api/baseline":
            return self._baseline(parse_qs(u.query))
        if u.path != "/api/events":
            return super().do_GET()
        d = self._review_dir(parse_qs(u.query))
        if not d:
            return self._json({"error": "bad dir"}, 400)
        events: list[StoredEvent] = []
        for actor in ("human", "agent"):
            p = d / actor
            try:
                actor_is_dir = p.is_dir()
            except (OSError, ValueError):
                actor_is_dir = False
            if not actor_is_dir:
                continue
            for entry in p.iterdir():
                name = entry.name
                try:
                    with entry.open() as f:
                        events.append({"actor": actor, "name": name, "body": json.load(f)})
                except (OSError, ValueError):
                    pass
        events.sort(key=lambda e: e["name"])
        self._json(events)
        return None

    def do_POST(self) -> None:
        u = urlparse(self.path)
        if u.path != "/api/events":
            return self._json({"error": "not found"}, 404)
        q = parse_qs(u.query)
        d = self._review_dir(q)
        actor = q.get("actor", ["human"])[0]
        if not d or actor not in ("human", "agent"):
            return self._json({"error": "bad dir or actor"}, 400)
        try:
            ev = json.loads(self.rfile.read(int(self.headers.get("Content-Length", 0))))
        except ValueError:
            return self._json({"error": "bad json"}, 400)
        event = ev.get("event")
        event_id = ev.get("id")
        safe = re.compile(r"[A-Za-z0-9._-]{1,128}")
        if (
            not isinstance(event, str)
            or not isinstance(event_id, str)
            or not safe.fullmatch(event)
            or not safe.fullmatch(event_id)
        ):
            return self._json({"error": "bad event name"}, 400)
        (d / actor).mkdir(parents=True, exist_ok=True)
        name = "{:d}-{!s}-{!s}.json".format(*(time.time_ns(), event, event_id))
        with (d / actor / name).open("w") as f:
            json.dump(ev, f)
        self._json({"ok": True, "name": name})
        return None


if __name__ == "__main__":
    server = HTTPServer((BIND, port), Handler)
    port = server.server_port
    host = advertised_host()
    print(
        "spec-chat review-serve on http://{!s}:{:d}  root={!s}".format(*(host, port, ROOT)),
        flush=True,
    )
    print("review URL is the secret; stop this process when review ends", flush=True)
    server.serve_forever()

